// fast for n up to 90
pub fn fib(n: u32) -> u64 {
    if n <= 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }
    let mut a = 0;
    let mut b = 1;
    for _ in 2..n {
        let temp = a;
        a = b;
        b = temp + b;
    }
    b
}

