use std::str::FromStr;

pub fn rle(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut chars: Vec<char> = input.chars().collect();
    let mut count: u32 = 1;
    let mut chars: Vec<char> = chars.clone();

    for i in 1..chars.len() {
        if chars[i] == chars[0] {
            count += 1;
        } else {
            chars.push(chars[i]);
            chars.clear();
            count = 1;
        }
    }

    let mut result = String::new();
    for (i, c) in chars.iter().enumerate() {
        if i == 0 {
            result.push(c);
        } else {
            result.push_str(&format!("{}{}", count, c));
        }
    }

    result
}

