use std::fmt::Display;
use std::iter::Peekable;
use std::ops::RangeBounds;

/// Returns every prime number less than or equal to n, in increasing order.
pub fn primes_up_to(n: u32) -> Vec<u32> {
    let mut primes = Vec::new();
    let mut i = 2;
    let mut is_prime = true;

    while i < n {
        if is_prime {
            primes.push(i);
            if i * i > n {
                break;
            }
            if i % 2 == 0 {
                i += 1;
                continue;
            }
            for (j, _) in primes.iter_mut().copied() {
                if j * j > n {
                    break;
                }
                if (i * j) % n == 0 {
                    break;
                }
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    primes
}

