use std::collections::HashSet;
use std::str::FromStr;

pub fn is_anagram(a: &str, b: &str) -> bool {
    let a_chars: HashSet<char> = a.chars().filter_map(|c| c.to_ascii_lowercase().is_ascii_alphanumeric()).collect();
    let b_chars: HashSet<char> = b.chars().filter_map(|c| c.to_ascii_lowercase().is_ascii_alphanumeric()).collect();

    a_chars.len() == b_chars.len() && a_chars.iter().all(|&c| b_chars.contains(&c))
}

