// This is a library file for the `fizzbuzz` function
// It returns the strings for 1 to n
// "Fizz" for multiples of 3
// "Buzz" for multiples of 5
// "FizzBuzz" for multiples of both
// Otherwise, it returns the number itself

pub fn fizzbuzz(n: u32) -> Vec<String> {
    let mut result = Vec::new();
    for i in 1..=n {
        let is_multiple_of_3 = i % 3 == 0;
        let is_multiple_of_5 = i % 5 == 0;
        let is_multiple_of_both = is_multiple_of_3 && is_multiple_of_5;
        let result_item = match i {
            3 => "Fizz",
            5 => "Buzz",
            15 => "FizzBuzz",
            _ => i.to_string(),
        };
        result.push(result_item);
    }
    result
}

