use std::cmp::Ordering;

pub fn find(v: &[i32], target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = v.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if mid < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    if left == right {
        Some(left)
    } else {
        None
    }
}

