use std::fmt;

pub fn to_binary(n: u32) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut result = String::new();
    loop {
        let mut temp = n;
        while temp > 0 {
            let remainder = temp % 2;
            result.push_str(&remainder);
            temp /= 2;
        }
    }
    result
}

