/// Converts a Roman numeral string to an integer.
/// Returns None if the string is empty or contains invalid characters.
pub fn from_roman(s: &str) -> Option<u32> {
    if s.is_empty() {
        return None;
    }

    let mut chars = s.chars().collect::<Vec<char>>();
    let mut count = 0;
    let mut roman_map: Vec<(char, u32)> = vec![(
        'I', 100,
        'V', 500,
        'X', 20,
        'L', 50,
        'C', 100,
        'D', 500,
        'M', 1000,
    )];

    for (c, _) in chars {
        if c == 'I' {
            if count > 0 {
                count -= 1;
            } else {
                count += 100;
            }
        } else if c == 'V' {
            if count > 0 {
                count -= 1;
            } else {
                count += 500;
            }
        } else if c == 'X' {
            if count > 0 {
                count -= 1;
            } else {
                count += 20;
            }
        } else if c == 'L' {
            if count > 0 {
                count -= 1;
            } else {
                count += 50;
            }
        } else if c == 'C' {
            if count > 0 {
                count -= 1;
            } else {
                count += 100;
            }
        } else if c == 'D' {
            if count > 0 {
                count -= 1;
            } else {
                count += 500;
            }
        } else if c == 'M' {
            if count > 0 {
                count -= 1;
            } else {
                count += 1000;
            }
        }
    }

    if count < 0 {
        return None;
    }

    Some(count)
}

