use std::collections::HashSet;

pub fn is_balanced(s: &str) -> bool {
    let mut open_count = HashSet::new();
    let mut close_count = HashSet::new();

    for (char, _) in s.chars() {
        match char {
            // Open brackets
            '(' => open_count.insert('(', true),
            '[' => open_count.insert('[', true),
            '{' => open_count.insert('{', true),
            // Close brackets
            ')' => close_count.insert(')', true),
            ']' => close_count.insert(']', true),
            '}' => close_count.insert('}', true),
            // Ignore other characters
            _ => (),
        }
    }

    open_count.is_empty() && close_count.is_empty()
}

