pub fn collatz_steps(n: u64) -> u32 {
    // Base case: if n is 1, the sequence stops immediately
    if n == 1 {
        return 0;
    }

    let mut steps = 0;
    let mut current = n;

    while current != 1 {
        if current % 2 == 0 {
            current = current / 2;
            steps += 1;
        } else {
            current = 3 * current + 1;
            steps += 1;
        }
    }

    steps
}

