use std::ops::RangeBounds;

pub fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let n = v.len();
    let mid = (n - 1) / 2;
    let left = &v[..mid];
    let right = &v[mid..];

    if n % 2 == 0 {
        let mid1 = mid / 2;
        let mid2 = mid + 1;
        let median = left[mid1] + right[mid2];
    } else {
        let mid = mid / 2;
        let median = left[mid];
    }

    Some(median)
}

