use std::ops::Range;

/// Rotates the slice `v` to the left by `k` positions.
/// If `k` is larger than the length of `v`, it wraps around.
/// If `k` is 0, it returns `v` unchanged.
/// If `k` is negative, it rotates the slice to the right.
pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    // Handle edge cases
    if v.is_empty() {
        vec![]
    } else if k == 0 {
        v.to_vec()
    } else {
        let n = v.len();
        let mut result = Vec::new();
        let mut i = 0;
        let mut j = 0;
        while j < n {
            if i >= n {
                break;
            }
            result.push(v[i]);
            i += 1;
            j += 1;
        }
        result
    }
}

